input.sparql:
SELECT ?point_uri ?power_id ?occupancy_id WHERE {
  ?zone a brick:Zone ;
    rdfs:label "Perimeter_top_ZN_4" ;
    brick:hasPoint ?power_point, ?occupancy_point .
  ?power_point a brick:Lighting_Power_Sensor ;
    ref:hasTimeseriesId ?power_id .
  ?occupancy_point a brick:Occupancy_Sensor ;
    ref:hasTimeseriesId ?occupancy_id .
  ?power_point ref:hasExternalReference ?point_uri .
}
